using EEMS.Modules.Inventory.Domain;namespace EEMS.UnitTests.Inventory;
public sealed class InventoryTests{[Fact]public void MovementRequiresEndpoint()=>Assert.Throws<ArgumentException>(()=>StockMovement.Record(Guid.NewGuid(),Guid.NewGuid(),1,null,null,Guid.NewGuid(),1,"R"));[Fact]public void MovementRejectsSameWarehouse(){var warehouse=Guid.NewGuid();Assert.Throws<ArgumentException>(()=>StockMovement.Record(Guid.NewGuid(),Guid.NewGuid(),1,warehouse,warehouse,Guid.NewGuid(),1,"R"));}[Fact]public void AllocationRequiresDestination()=>Assert.Throws<ArgumentException>(()=>StockAllocation.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),null,null,Guid.NewGuid(),1,1));[Fact]public void AllocationCanOnlyBeAcknowledgedOnce(){var allocation=StockAllocation.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),null,Guid.NewGuid(),1,1);allocation.Acknowledge();Assert.Throws<InvalidOperationException>(allocation.Acknowledge);}}
